36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a leading '+' and 8 to 15 digits)")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "postcode")
73	    private String postcode;
74	
75	    /**
76	     * Whether this owner was flagged as a suspected soft-duplicate of an existing owner. Retained
77	     * as part of the API/persistence contract but always {@code false} under the current
78	     * household-keyed rule: an owner sharing an existing owner's {@code lastName} and
79	     * {@code postcode} is now the same household, so it is either rejected as a household duplicate
80	     * (409) or admitted as a declared {@code sharesHousehold} member — and a declared member is not
81	     * a suspected duplicate. No production code path sets this field.
82	     */
83	    @Column(name = "possible_duplicate")
84	    private boolean possibleDuplicate;
85	
86	    /**
87	     * The id of the existing owner this owner soft-matches, set together with
88	     * {@link #isPossibleDuplicate()}. Retained for contract compatibility but always {@code null}
89	     * under the current household-keyed rule (see {@link #isPossibleDuplicate()}); no production
90	     * code path sets it.
91	     */
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    /**
96	     * Write-only, non-persistent acknowledgement that this owner deliberately shares a
97	     * household with an existing owner. When {@code true}, creation is allowed even if
98	     * another owner already has the same lastName and address.
99	     */
100	    @Transient
101	    private boolean sharesHousehold;
102	
103	    /**
104	     * Read-only, non-persistent count of the owners that share this owner's {@code householdId}
105	     * (including this owner), populated by the service when an owner is loaded for presentation.
106	     * Zero when the owner belongs to no household. Used to derive the membership tier.
107	     */
108	    @Transient
109	    private int householdSize;
110	
111	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
112	    private Set<Pet> pets;
