135	        this.telephone = telephone;
136	    }
137	
138	    public String getEmail() {
139	        return this.email;
140	    }
141	
142	    public void setEmail(String email) {
143	        this.email = email;
144	    }
145	
146	    public LocalDate getRegistrationDate() {
147	        return this.registrationDate;
148	    }
149	
150	    public void setRegistrationDate(LocalDate registrationDate) {
151	        this.registrationDate = registrationDate;
152	    }
153	
154	    public LocalDate getBirthDate() {
155	        return this.birthDate;
156	    }
157	
158	    public void setBirthDate(LocalDate birthDate) {
159	        this.birthDate = birthDate;
160	    }
161	
162	    /**
163	     * The owner's age band derived from {@code birthDate} measured against {@code registrationDate}:
164	     * {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
165	     * over. Returns null when either the birth date or the registration date is not set.
166	     */
167	    public String getAgeBand() {
168	        if (this.birthDate == null || this.registrationDate == null) {
169	            return null;
170	        }
171	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
172	        if (age < 18) {
173	            return "MINOR";
174	        }
175	        if (age < 65) {
176	            return "ADULT";
177	        }
178	        return "SENIOR";
179	    }
180	
181	    public String getCustomerCode() {
182	        return this.customerCode;
183	    }
184	
185	    public void setCustomerCode(String customerCode) {
186	        this.customerCode = customerCode;
187	    }
188	
189	    public String getHouseholdId() {
190	        return this.householdId;
191	    }
192	
193	    public void setHouseholdId(String householdId) {
194	        this.householdId = householdId;
195	    }
196	
197	    public Integer getNamesakeCount() {
198	        return this.namesakeCount;
199	    }
200	
201	    public void setNamesakeCount(Integer namesakeCount) {
202	        this.namesakeCount = namesakeCount;
203	    }
204	
205	    public String getPostcode() {
206	        return this.postcode;
207	    }
