229	    /** The highest membership level assignable on creation; level 4 is reserved for tenure. */
230	    public static final int MAX_MEMBERSHIP_LEVEL = 3;
231	
232	    /**
233	     * The owner's numeric membership level, computed from stored fields: it starts at 1, gains 1
234	     * when an email is present, gains 1 when {@code namesakeCount} is 0, and is capped at
235	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
236	     */
237	    public int getMembershipLevel() {
238	        int level = 1;
239	        if (this.email != null && !this.email.isEmpty()) {
240	            level++;
241	        }
242	        if (this.namesakeCount != null && this.namesakeCount == 0) {
243	            level++;
244	        }
245	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
246	    }
247	
248	    /**
249	     * The derived identity key used to detect duplicate owners: the (already normalized) telephone,
250	     * the email or empty, and the {@code householdId} or empty, joined with {@code '|'}. This single
251	     * key consolidates the former separate telephone, email and household duplicate rules — two
252	     * owners are duplicates only when their whole identity keys are equal. Because the telephone is
253	     * part of the key, two members of the same household (same {@code householdId}) with different
254	     * telephones have different keys and are both allowed.
255	     */
256	    public String getIdentityKey() {
257	        String tel = this.telephone == null ? "" : this.telephone;
258	        String mail = this.email == null ? "" : this.email;
259	        String household = this.householdId == null ? "" : this.householdId;
260	        return tel + "|" + mail + "|" + household;
261	    }
262	
263	    /**
264	     * A single Luhn check digit (0-9) computed over the digits contained in {@code customerCode},
265	     * or null when the {@code customerCode} has not been assigned.
266	     */
267	    public Integer getCheckDigit() {
268	        if (this.customerCode == null) {
269	            return null;
270	        }
271	        int sum = 0;
272	        boolean dbl = true;
273	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
274	            char c = this.customerCode.charAt(i);
275	            if (c < '0' || c > '9') {
276	                continue;
277	            }
278	            int d = c - '0';
279	            if (dbl) {
280	                d *= 2;
281	                if (d > 9) {
282	                    d -= 9;
283	                }
284	            }
285	            sum += d;
286	            dbl = !dbl;
287	        }
288	        return (10 - (sum % 10)) % 10;
289	    }
290	
291	    public boolean isSharesHousehold() {
292	        return this.sharesHousehold;
293	    }
294	
295	    public void setSharesHousehold(boolean sharesHousehold) {
296	        this.sharesHousehold = sharesHousehold;
297	    }
298	
299	    public int getHouseholdSize() {
300	        return this.householdSize;
301	    }
302	
303	    public void setHouseholdSize(int householdSize) {
304	        this.householdSize = householdSize;
305	    }
306	
307	    protected Set<Pet> getPetsInternal() {
308	        if (this.pets == null) {
309	            this.pets = new HashSet<>();
310	        }
311	        return this.pets;
312	    }
313	
314	    protected void setPetsInternal(Set<Pet> pets) {
315	        this.pets = pets;
316	    }
317	
318	    public List<Pet> getPets() {
319	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
320	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
321	        return Collections.unmodifiableList(sortedPets);
322	    }
323	
324	    public void setPets(List<Pet> pets) {
325	        this.pets = new HashSet<>(pets);
326	    }
327	
328	    public void addPet(Pet pet) {
329	        getPetsInternal().add(pet);
330	        pet.setOwner(this);
331	    }
332	
333	    /**
334	     * Return the Pet with the given name, or null if none found for this Owner.
335	     *
336	     * @param name to test
337	     * @return true if pet name is already in use
338	     */
339	    public Pet getPet(String name) {
340	        return getPet(name, false);
341	    }
342	
343	    /**
344	     * Return the Pet with the given name, or null if none found for this Owner.
345	     *
346	     * @param name to test
347	     * @return true if pet name is already in use
348	     */
349	    public Pet getPet(String name, boolean ignoreNew) {
350	        name = name.toLowerCase();
351	        for (Pet pet : getPetsInternal()) {
352	            if (!ignoreNew || !pet.isNew()) {
353	                String compName = pet.getName();
354	                compName = compName.toLowerCase();
355	                if (compName.equals(name)) {
356	                    return pet;
357	                }
358	            }
359	        }
360	        return null;
361	    }
362	
363	    public Pet getPet(Integer petId) {
364	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
365	    }
366	
367	    @Override
368	    public String toString() {
369	        return new ToStringCreator(this)
370	
371	            .append("id", this.getId())
372	            .append("new", this.isNew())
373	            .append("lastName", this.getLastName())
374	            .append("firstName", this.getFirstName())
375	            .append("address", this.address)
376	            .append("city", this.city)
377	            .append("telephone", this.telephone)
378	            .toString();
379	    }
380	}
